// DEMO-2 — DAG node now carries a kill button for running sessions.
import { useRef, useState } from "react";
import { ConfirmModal } from "./ConfirmModal";
import { useSessions } from "../hooks/useSessions";

export function DagView() {
  const sessions = useSessions();
  const [target, setTarget] = useState<string | null>(null);
  const buttonRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const dismiss = () => {
    const ref = target ? buttonRefs.current[target] : null;
    setTarget(null);
    ref?.focus();
  };
  return (
    <div className="dag">
      {sessions.map((s) => (
        <div key={s.id} className="dag-node" data-status={s.status}>
          <span className="id">{s.id}</span>
          <span className="agent">{s.agent}</span>
          {s.status === "running" ? (
            <button
              ref={(el) => (buttonRefs.current[s.id] = el)}
              className="kill"
              aria-label={`Kill agent ${s.id}`}
              onClick={() => setTarget(s.id)}
            >
              Kill
            </button>
          ) : null}
        </div>
      ))}
      {target ? <ConfirmModal targetId={target} onDismiss={dismiss} /> : null}
    </div>
  );
}

