// DEMO-2 — the kill confirmation modal. Focus trap + Esc close.
import { useEffect, useRef } from "react";

export function ConfirmModal({ targetId, onDismiss }: { targetId: string; onDismiss: () => void }) {
  const confirmRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    confirmRef.current?.focus();
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onDismiss(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onDismiss]);
  return (
    <div className="modal" role="dialog" aria-modal="true" aria-labelledby="kill-title">
      <h2 id="kill-title">Kill agent {targetId}?</h2>
      <p>Any uncommitted work will be lost.</p>
      <button onClick={onDismiss}>Cancel</button>
      <button ref={confirmRef} className="danger" onClick={() => { /* DEMO-3: invoke MCP */ onDismiss(); }}>Kill</button>
    </div>
  );
}
